using System;using Game.Components;using Game.Simulation;using Unity.Entities;using Game.Configs;using Game.Skirmish.Contracts;
namespace Game.Runtime {
// Hot reads check captured launch/session identity only; arbitrary in-place array mutation is not detected here.
// Full compiler/hash/source checks belong to startup and publication boundaries.
// Data-family check only. SourceAdmittedProfiles owns executable mission/seed admission.
internal static class SourceGroundMissionFamily {
 internal static void RequirePaidCatalogSetup(SkirmishResolvedSetup setup){if(setup?.CatalogId=="S003"){SourcePaidCatalogSetupGuard.RequireS003(setup);return;}if(setup!=null&&SkirmishGenericAirCombinedEnemyRollout.IncludesCatalog(setup.CatalogId)){if(!SkirmishGenericAirCombinedEnemyRollout.Supports(setup)||!SkirmishMissionLogicalBindingCompiler.RequiresBinding(setup)||string.IsNullOrEmpty(setup.MissionLogicalBindingFingerprint)||setup.EnemyPolicy==null||setup.SetupHash!=SkirmishSetupCompiler.ComputeHash(setup,setup.Seed)||SkirmishMissionDispatch.TryGetLegacyIndex(setup.CatalogId,out _))throw new NotSupportedException("Actual compiled source-only air paid catalog setup required");return;}RequireCatalogSetup(setup);}
 internal static void RequireCatalogSetup(SkirmishResolvedSetup setup){RequireCatalogIdentity(setup);if(setup.CatalogId!="S002"&&!SkirmishGenericGroundEnemyRollout.Supports(setup))throw new NotSupportedException("Original generic-ground capability boundary rejected");}
 internal static void RequireCatalogIdentity(SkirmishResolvedSetup setup){
  if(setup==null)throw new NotSupportedException("Actual retained source setup required");
  if(setup.CatalogId=="S002")return; // Preserve the existing source catalog scope.
  if(!new SkirmishCatalogId(setup.CatalogId).IsValid||setup.DefinitionId!="skirmish."+setup.CatalogId.ToLowerInvariant()||setup.ObjectiveKind!=SkirmishObjectiveKind.BaseAssault||setup.ArmyProfileId!=SkirmishArmyProfileId.GroundManeuver||!GroundMissionContext.SupportsOriginalGroundStart(setup.StartPackageId,setup.Readiness)||string.IsNullOrEmpty(setup.LayoutBindingFingerprint)||string.IsNullOrEmpty(setup.MissionLogicalBindingFingerprint)||setup.EnemyPolicy==null)throw new NotSupportedException("Actual source-compiled source/logical-bound BA/G/Field-or-Established ground-family identity required");
 }
 internal static int SourcePresetLoadIndex(SkirmishResolvedSetup setup,int playableIndex){if(setup?.CatalogId=="S003")RequirePaidCatalogSetup(setup);else RequireCatalogIdentity(setup);if(SkirmishMissionDispatch.TryGetLegacyIndex(setup.CatalogId,out int original)){if(playableIndex!=original)throw new NotSupportedException("Original coded dispatch required");return original;}if(playableIndex!=-1)throw new NotSupportedException("Source-only compiled mission must retain Planned/-1");return SkirmishPresetConfig.SourcePresetIndex(-1);}
 // This admission belongs only to owners explicitly supporting the air-derived
 // source domain. It does not grant ground ARIA or player-command capability.
 internal static SkirmishResolvedSetup QualifyAirSourceSession(EntityManager em,Entity session){
  if(em==null||!em.Exists(session)||!em.HasComponent<SkirmishResolvedSetupRecord>(session))throw new NotSupportedException("Actual compiled air source session required");
  var setup=em.GetComponentObject<SkirmishResolvedSetupRecord>(session).Setup;
  if(setup==null||!SkirmishGenericAirCombinedEnemyRollout.Supports(setup)||!SkirmishMissionLogicalBindingCompiler.RequiresBinding(setup)||string.IsNullOrEmpty(setup.MissionLogicalBindingFingerprint)||setup.EnemyPolicy==null||setup.SetupHash!=SkirmishSetupCompiler.ComputeHash(setup,setup.Seed)||SkirmishMissionDispatch.TryGetLegacyIndex(setup.CatalogId,out _))throw new NotSupportedException("Actual compiled source-only air transform setup required");
  RequireAirSourceSessionIdentity(em,session,setup);return setup;
 }
 internal static void RequireAirSourceSessionIdentity(EntityManager em,Entity session,SkirmishResolvedSetup qualified){
  if(em==null||qualified==null||!em.Exists(session)||!em.HasComponent<SkirmishResolvedSetupRecord>(session)||!em.HasComponent<SkirmishExpandedSessionComponent>(session)||!em.HasComponent<SkirmishMatchState>(session)||!em.HasComponent<SkirmishLaunchDefinitionRecord>(session)||!ReferenceEquals(em.GetComponentObject<SkirmishResolvedSetupRecord>(session).Setup,qualified))throw new NotSupportedException("Actual qualified same-world air transform session required");
  var state=em.GetComponentData<SkirmishExpandedSessionComponent>(session);var match=em.GetComponentData<SkirmishMatchState>(session);var launch=em.GetComponentObject<SkirmishLaunchDefinitionRecord>(session);
  if(state.IsLegacy!=0||state.SessionId.IsEmpty||state.SessionId!=match.SessionId||state.CatalogId.ToString()!=qualified.CatalogId||state.DefinitionId.ToString()!=qualified.DefinitionId||state.ContentVersion!=qualified.ContentVersion||state.SetupHash!=qualified.SetupHash||state.Seed!=qualified.Seed||match.Seed!=qualified.Seed||state.SizeId!=qualified.SizeId||state.DifficultyId!=qualified.DifficultyId||state.ObjectiveKind!=qualified.ObjectiveKind||match.ScenarioIndex!=-1||launch==null||!launch.MatchesIdentity(qualified,state))throw new NotSupportedException("Compiled air transform session identity changed");
 }
 internal static SkirmishResolvedSetup RequireSession(EntityManager em,Entity session,bool allowS003FreshLifetime=false){if(em==null||!em.Exists(session)||!em.HasComponent<SkirmishResolvedSetupRecord>(session)||!em.HasComponent<SkirmishExpandedSessionComponent>(session)||!em.HasComponent<SkirmishMatchState>(session)||!em.HasComponent<SkirmishLaunchDefinitionRecord>(session))throw new NotSupportedException("Actual compiled source session required");var setup=em.GetComponentObject<SkirmishResolvedSetupRecord>(session).Setup;if(allowS003FreshLifetime&&setup?.CatalogId=="S003")RequirePaidCatalogSetup(setup);else RequireCatalogIdentity(setup);var state=em.GetComponentData<SkirmishExpandedSessionComponent>(session);var match=em.GetComponentData<SkirmishMatchState>(session);var launch=em.GetComponentObject<SkirmishLaunchDefinitionRecord>(session);if(state.IsLegacy!=0||state.SessionId.IsEmpty||state.SessionId!=match.SessionId||state.CatalogId.ToString()!=setup.CatalogId||state.DefinitionId.ToString()!=setup.DefinitionId||state.ContentVersion!=setup.ContentVersion||state.SetupHash!=setup.SetupHash||state.Seed!=setup.Seed||match.Seed!=setup.Seed||state.SizeId!=setup.SizeId||state.DifficultyId!=setup.DifficultyId||state.ObjectiveKind!=setup.ObjectiveKind||launch==null||!launch.MatchesIdentity(setup,state))throw new NotSupportedException("Compiled source session identity changed");if(allowS003FreshLifetime&&setup.CatalogId=="S003"){if(!SkirmishMissionDispatch.TryGetLegacyIndex(setup.CatalogId,out int sourceIndex)||match.ScenarioIndex!=sourceIndex)throw new NotSupportedException("Original S003 dispatch required");}else SourcePresetLoadIndex(setup,match.ScenarioIndex);return setup;}
 internal static int SourceLogicalPresetLoadIndex(SkirmishResolvedSetup setup,int playableIndex){if(setup!=null&&SkirmishGenericAirCombinedEnemyRollout.IncludesCatalog(setup.CatalogId)){RequirePaidCatalogSetup(setup);if(playableIndex!=-1)throw new NotSupportedException("Source-only air mission must retain Planned/-1");return SkirmishPresetConfig.SourcePresetIndex(-1);}return SourcePresetLoadIndex(setup,playableIndex);}
 internal static SkirmishResolvedSetup RequireLogicalSourceSession(EntityManager em,Entity session,in GroundMissionContext context){var setup=context.ValidatedExpandedAirBaseAssault?QualifyAirSourceSession(em,session):RequireSession(em,session,context.CatalogId=="S003");RequireLogicalContext(context,setup,em.GetComponentData<SkirmishExpandedSessionComponent>(session),em.GetComponentData<SkirmishMatchState>(session).ScenarioIndex);return setup;}
 internal static void RequireLogicalContext(in GroundMissionContext context,SkirmishResolvedSetup setup,in SkirmishExpandedSessionComponent state,int playableIndex){if(context.ValidatedExpandedAirBaseAssault)RequirePaidCatalogSetup(setup);else if(setup?.CatalogId=="S003")RequirePaidCatalogSetup(setup);else RequireCatalogIdentity(setup);if(context.ObservationScope!=AriaS002Scope.LogicalPublicData||context.SourcePresetLoadIndex!=SourceLogicalPresetLoadIndex(setup,playableIndex)||!GroundMissionContextFactory.MatchesLogicalSession(context,setup,state,playableIndex))throw new NotSupportedException("Exact compiled logical family context/session required");}

}
}
